(() => {
  // E2E only: publishes a small open-land revision through window.seed.cartridges.publish — the
  // same IPC Create's Build ends with — so main's publish-time licence audit runs on a picture.
  // No screen reaches a publish with a picture while the model is the fixture (it only says
  // "Hello."), so the revision is made from the built-in world's origin scene.
  const bytesOf = (b64) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  const pictures = {
    // the fixture upstream's 64 x 64 PNG, never drawn through this app: no licence record → unknown
    unknownA: async () => bytesOf("iVBORw0KGgoAAAANSUhEUgAAAEAAAABACAIAAAAlC+aJAAAAeklEQVR4nO3PUQkAIBTAwBfVKEYxqiH8OITBAtxm7fN1wwUNaEEDWtCAFjSgBQ1oQQNa0IAWNKAFDWhBA1rQgBY0oAUNaEEDWtCAFjSgBQ1oQQNa0IAWNKAFDWhBA1rQgBY0oAUNaEEDWtCAFjSgBQ1oQQNa0IAWPHYBHwIBadNjfowAAAAASUVORK5CYII="),
    // another picture nobody drew here: a 64 x 64 canvas fill → unknown
    unknownB: async () => {
      const c = new OffscreenCanvas(64, 64); const g = c.getContext("2d");
      g.fillStyle = "rgb(40, 90, 200)"; g.fillRect(0, 0, 64, 64);
      return new Uint8Array(await (await c.convertToBlob({ type: "image/png" })).arrayBuffer());
    },
    // a look sketch drawn through the gateway (test-image, apache-2.0) in p4-images-hosted
    hosted: async () => {
      const looks = await window.seed.createDrafts.looks("81e0650a3a32abcd");
      return bytesOf(looks.value[0].dataUrl.slice("data:image/png;base64,".length));
    },
  };
  window.__lic = async (version, parentVersion, picture) => {
    const { openLandCartridge } = await import("/narrative/openLandCartridge.ts");
    const base = await window.seed.cartridges.read("aether-land", "1.3.0");
    if (!base.ok) return base;
    const input = await openLandCartridge({
      cartridgeId: "e2e-look", version, name: "E2E licence audit", author: "e2e",
      premise: "A revision made to exercise the publish-time licence audit.",
      originSource: base.value.scenes.origin, bible: base.value.bible,
      createdAt: new Date().toISOString(), look: await pictures[picture](),
    });
    if (!input.ok) return input;
    let lineage = input.value.manifest.lineage ?? null;
    if (parentVersion !== null) {
      const list = await window.seed.cartridges.list();
      const parent = list.value.find((m) => m.cartridgeId === "e2e-look" && m.version === parentVersion);
      lineage = { kind: "revision", parent: { cartridgeId: parent.cartridgeId, version: parent.version, contentHash: parent.contentHash } };
    }
    const published = await window.seed.cartridges.publish({ ...input.value, manifest: { ...input.value.manifest, lineage } });
    if (!published.ok) return { version, picture, refused: published.error };
    const rev = await window.seed.cartridges.read("e2e-look", version);
    const licences = rev.ok ? new TextDecoder().decode(rev.value.assets["licences.json"]) : null;
    return { version, picture, published: published.value.contentHash, lineage: published.value.lineage, licences };
  };
  return "defined";
})()
